"""The examples generated by a system dynamics model (sdlab/examples/sd-*): their truth model is the
system, so they must run for as long as anyone lets them, stay sane, and keep their answer key true."""

import json
import math
import subprocess
import sys

import pytest

from sdlab.sdtruth import Truth, write_truth
from sdlab.server import EXAMPLES, validate

SD = sorted(p.parent.name for p in EXAMPLES.glob("sd-*/truth.model.json"))


def truth(example: str) -> Truth:
    return Truth(EXAMPLES / example / "truth.model.json")


def test_there_are_ground_truth_examples():
    assert len(SD) >= 5, SD


@pytest.mark.parametrize("example", SD)
def test_the_example_shows_only_the_measured_stocks_and_no_flows(example):
    model, t = json.loads((EXAMPLES / f"{example}.json").read_text()), truth(example)
    assert validate(model) == []
    assert [s["id"] for s in model["stocks"]] == t.measured_ids
    assert model["flows"] == [] and model["machines"] == []
    assert all(s["id"] in t.stock_ids for s in model["stocks"])
    assert validate({**t.model, "stocks": [{k: v for k, v in s.items() if k != "measured"} for s in t.model["stocks"]]}) == [], "the truth is itself a valid SD Lab model"


@pytest.mark.parametrize("example", SD)
def test_a_very_long_run_stays_sane(example):
    """Fifty times the default length: every level finite and never negative, the stocks that are
    not final stay within reach of where they were in the first period, and everything that moved
    is accounted for (each stock's change is its inflows minus its outflows)."""
    t = truth(example)
    n = t.steps * 50
    r = t.run(steps=n)
    first = {s: max(v[: t.steps]) for s, v in r["levels"].items()}
    final = {s["id"] for s in t.model["stocks"] if s.get("final")}
    for s, v in r["levels"].items():
        assert len(v) == n and all(math.isfinite(x) and x >= 0 for x in v), s
        if s not in final:
            assert max(v) <= 5 * first[s] + 50, f"{s} grew from at most {first[s]} to {max(v)}"
    start = {s["id"]: s.get("initial") or 0 for s in t.model["stocks"]}
    for s in t.stock_ids:
        net = sum(sum(r["counters"][f["id"]]) for f in t.model["flows"] if f.get("to") == s) \
            - sum(sum(r["counters"][f["id"]]) * float(f.get("ratio") or 1) for f in t.model["flows"] if f.get("from") == s)
        assert abs(start[s] + net - r["levels"][s][-1]) < 1e-6 * max(1, abs(net)) + 1, s


@pytest.mark.parametrize("example", SD)
def test_a_longer_run_begins_with_the_shorter_one(example):
    """So a live run can go on forever: the feed extends its recording and nothing earlier changes."""
    t = truth(example)
    short, long = t.measured(steps=t.steps), t.measured(steps=t.steps * 3)
    assert {s: v[: t.steps] for s, v in long["levels"].items()} == short["levels"]
    assert [e for e in long["eras"] if e["start"] <= t.steps] == short["eras"]


@pytest.mark.parametrize("example", SD)
def test_history_prints_what_measured_returns(example):
    p = subprocess.run([sys.executable, str(EXAMPLES / example / "machines" / "history.py")], input="",
                       capture_output=True, text=True, timeout=60, cwd=EXAMPLES / example / "machines")
    assert p.returncode == 0, p.stderr
    rows = [json.loads(line) for line in p.stdout.splitlines()]
    m = truth(example).measured()
    assert [r["t"] for r in rows] == m["t"]
    assert {s: [r["levels"][s] for r in rows] for s in m["levels"]} == m["levels"]
    assert [{"start": r["t"], "label": r["era"]} for r in rows if "era" in r] == m["eras"][1:]


@pytest.mark.parametrize("example", SD)
def test_the_live_feed_never_runs_out(example, monkeypatch):
    t = truth(example)
    far = t.long_steps * 3 + 7
    p = subprocess.run([sys.executable, str(EXAMPLES / example / "machines" / "live.py")],
                       input=json.dumps({"t": far, "stocks": [{"id": s} for s in t.measured_ids]}),
                       capture_output=True, text=True, timeout=120, cwd=EXAMPLES / example / "machines",
                       env={**__import__("os").environ, "SDLAB_LIVE_STEPS": ""})
    assert p.returncode == 0, p.stderr
    row = json.loads(p.stdout)
    assert set(row["levels"]) == set(t.measured_ids)


@pytest.mark.parametrize("example", SD)
def test_the_answer_key_is_current(example, tmp_path):
    out = tmp_path / "truth.json"
    write_truth(truth(example), out)
    assert json.loads(out.read_text()) == json.loads((EXAMPLES / example / "truth.json").read_text())
